const app = document.getElementById("app");
const authDialog = document.getElementById("authDialog");
const authForm = document.getElementById("authForm");
const toastEl = document.getElementById("toast");
const COMMUNITY_RULES = [
"1. Запрещено оскорблять друг друга, провоцировать участников на конфликт и создавать дискомфортную атмосферу. Общение должно быть спокойным и не выходить за рамки приличия.\n\nИсключение: шуточные оскорбления, если обе стороны не против, воспринимают их как шутку, никому не обидно и это не доставляет дискомфорта другим участникам.",
"2. Категорически запрещено разжигать дискуссии на политические темы. Также запрещены фотографии, видео, кружки, гифки и другие материалы, связанные с политикой.",
"3. Запрещена дискриминация по любому признаку: расе, полу, религиозным убеждениям, политическим взглядам, роду занятий и т. д.",
"4. Запрещена целенаправленная травля участников с целью унижения. Нельзя приставать к человеку и подшучивать над ним, если вы видите, что это доставляет ему дискомфорт.\n\nИсключение: если никто не против ваших шуток, вы можете продолжать, но обязаны прекратить их по первой просьбе человека, в чей адрес они направлены, или других участников.",
"5. Запрещено подстрекать пользователей, админов и модераторов к нарушению правил.",
"6. Запрещены спам, флуд, чрезмерное упоминание пользователей, спам реакциями и злоупотребление капсом.",
"7. Запрещено рекламировать свои проекты и сторонние ресурсы в чате, а также распространять вредоносные ссылки.",
"8. Запрещено НАСТОЙЧИВО выпрашивать у участников и администрации личные данные: возраст, настоящее имя, место проживания, личные фотографии и всё в этом роде. Также строго запрещено разглашать личную информацию о другом человеке без его согласия.",
"9. Запрещён полноценный контент 18+ (фотографии, видео, гифки и тексты), в котором изображены или описаны интимные сцены и половые органы. Также запрещены расчленёнка, романтизация или подробное обсуждение суицида и другие материалы, способные вызвать отрицательную реакцию у участников группы.\n\nИсключение: обычные текстовые упоминания органов.\n\nПримечание: жёсткие ролевые тексты с подробным описанием сцен и тому подобного запрещены.",
"10. Запрещено оскорблять проект, его участников и их родителей. Оскорбления в шуточной форме допускаются только тогда, когда человек действительно воспринимает их как шутку. Подшучивая над кем-то, вы должны быть уверены, что собеседнику не обидно и это не перерастёт в конфликт."
];
let me = null, authMode = "login", activeTab = "home", socket = null, currentFilter = "Все", searchTerm = "", unreadCount = 0;

const api = async (url, options={}) => {
  const res = await fetch("/api" + url, { credentials:"same-origin", headers:{ ...(options.body instanceof FormData ? {} : {"Content-Type":"application/json"}), ...(options.headers||{}) }, ...options });
  const data = await res.json().catch(()=>({}));
  if (!res.ok) throw new Error(data.error || "Что-то пошло не так.");
  return data;
};
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const richText = value => esc(value).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/^### (.+)$/gm,'<h4>$1</h4>').replace(/^## (.+)$/gm,'<h3>$1</h3>').replace(/^# (.+)$/gm,'<h2>$1</h2>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>').replace(/(@[\p{L}\p{N}_-]{3,24})/gu,'<span class="chat-mention">$1</span>').replace(/\n/g,"<br>");
const SVG={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7H10v7H4a1 1 0 0 1-1-1z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.5a9 9 0 0 1-.9-4A8.5 8.5 0 0 1 12.5 3h.5a8.5 8.5 0 0 1 8 8z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.6.9L16 21h-8l-.2-2.1a8 8 0 0 1-1.6-.9l-1.7.6-1.4-2.4 1.4-1.1A8 8 0 0 1 4.5 13l-1.4-1.1 1.4-2.4 1.7.6a8 8 0 0 1 1.6-.9L8 7h8l.2 2.1a8 8 0 0 1 1.6.9l1.7-.6 1.4 2.4-1.4 1.1a8 8 0 0 1-.1 2.1z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',rules:'<path d="M8 4h11v17H5V7z"/><path d="M8 4v4H4M9 12h6M9 16h6"/>',report:'<path d="M4 4h16v16H4z"/><path d="m4 6 8 7 8-7"/>',idea:'<path d="M9 18h6M10 22h4M8 14a7 7 0 1 1 8 0c-.8.6-1 1.2-1 2H9c0-.8-.2-1.4-1-2z"/>',problem:'<path d="M12 3 2 21h20L12 3z"/><path d="M12 9v5m0 3h.01"/>',question:'<circle cx="12" cy="12" r="9"/><path d="M9.6 9a2.5 2.5 0 1 1 4.3 1.7c-1.2 1.1-1.9 1.4-1.9 3M12 17h.01"/>',news:'<path d="M4 5h16v15H4zM8 9h8M8 13h8M8 17h4"/>',complaint:'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/>',paperclip:'<path d="m21.4 11.1-8.5 8.5a5 5 0 0 1-7.1-7.1l9.2-9.2a3.5 3.5 0 0 1 5 5l-9.2 9.2a2 2 0 0 1-2.8-2.8l8.5-8.5"/>',edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/>',inbox:'<path d="M4 4h16v16H4z"/><path d="M4 13h4l2 3h4l2-3h4"/>',sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8Z"/><path d="m19 14 1 2.5 2.5 1-2.5 1L19 21l-1-2.5-2.5-1 2.5-1Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',loader:'<path d="M21 12a9 9 0 1 1-2.6-6.4"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(name)=>`<svg class="vicon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${SVG[name]||SVG.idea}</svg>`;
const categoryIcon=c=>icon(({"Идеи":"idea","Проблемы":"problem","Вопросы":"question","Новости":"news","Жалобы":"complaint"})[c]||"idea");
const reactionSet=[['heart','♥'],['like','👍'],['dislike','👎'],['fire','🔥'],['happy','☺']];
const reactionBar=(type,id,mine=null,counts=[])=>`<div class="reaction-bar">${reactionSet.map(([key,glyph])=>{const n=(counts||[]).find(x=>x.reaction===key)?.count||0;return `<button type="button" class="reaction-btn ${mine===key?'selected':''}" data-react-type="${type}" data-react-id="${id}" data-reaction="${key}" aria-label="${key}"><span>${glyph}</span>${n?`<small>${n}</small>`:''}</button>`}).join('')}</div>`;
const date = s => { const d = new Date(s.replace(" ","T")+"Z"); return isNaN(d) ? "" : d.toLocaleString("ru-RU",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}); };
function toast(text){toastEl.textContent=text;toastEl.className="toast";clearTimeout(toastEl._t);toastEl._t=setTimeout(()=>toastEl.className="",2600);}
function showAuth(mode){authMode=mode;document.getElementById("authTitle").textContent=mode==="login"?"С возвращением!":"Создать аккаунт";document.getElementById("nameField").classList.toggle("hidden",mode==="login");document.getElementById("authSubmit").textContent=mode==="login"?"Войти":"Зарегистрироваться";document.getElementById("authSwitch").innerHTML=mode==="login"?'Нет аккаунта? <button class="link-btn" id="switchAuth">Зарегистрироваться</button>':'Уже есть аккаунт? <button class="link-btn" id="switchAuth">Войти</button>';document.getElementById("switchAuth").onclick=()=>showAuth(mode==="login"?"register":"login");authDialog.showModal();}
document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>authDialog.close());
document.getElementById("startBtn").onclick=()=>showAuth("login");
authForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(authForm),payload=Object.fromEntries(fd);try{const d=await api(authMode==="login"?"/login":"/register",{method:"POST",body:JSON.stringify(payload)});me=d.user;authDialog.close();await boot();toast("Рады видеть тебя, "+me.username+"!");}catch(err){toast(err.message);}};

function navButton(id,iconName,label){return `<button class="nav-btn ${activeTab===id?"active":""}" data-tab="${id}">${icon(iconName)}<span>${label}</span></button>`;}
function layout(content,title="Главная"){
  app.innerHTML=`<div class="shell">
    <aside class="sidebar"><div class="brand-small"><span>✦</span> Sunshine Forum</div><nav class="side-nav">
      ${navButton("home","home","Главная")}${navButton("chat","chat","Общий чат")}${navButton("notifications","bell","Уведомления")}${navButton("settings","settings","Настройки")}${navButton("profile","user","Профиль")}${navButton("report","report","Обращение")}${navButton("rules","rules","Правила")}${["admin","moderator"].includes(me.role)?navButton("admin","settings","Админ-панель"):""}
    </nav><div class="sidebar-bottom"><button class="theme-toggle" id="themeBtn">☾　Тема</button><button class="nav-btn" id="logoutBtn">↪　Выйти</button></div></aside>
    <main class="main"><header class="topbar"><h1>✦ ${title}</h1><div class="user-chip"><button class="theme-toggle" id="themeBtnTop">☾</button><button class="profile-shortcut" id="myProfileShortcut" title="Открыть мой профиль"><span class="avatar">${me.avatar?`<img src="${esc(me.avatar)}?v=${Date.now()}" alt=""/>`:"🌸"}</span><b>${esc(me.username)}</b></button><span class="unread-badge" id="unreadBadge">${unreadCount||""}</span></div></header>${content}</main>
  </div><nav class="mobile-nav"><button data-tab="home">${icon("home")}Главная</button><button data-tab="chat">${icon("chat")}Чат</button><button data-tab="notifications">${icon("bell")}Уведомления</button><button data-tab="profile">${icon("user")}Профиль</button><button data-tab="rules">${icon("rules")}Правила</button>${["admin","moderator"].includes(me.role)?`<button data-tab="admin">${icon("settings")}Админ</button>`:""}</nav>`;
  document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>go(b.dataset.tab));
  document.getElementById("logoutBtn").onclick=async()=>{await api("/logout",{method:"POST"});location.reload();};
  const toggle=()=>{document.body.classList.toggle("dark");localStorage.setItem("sunshine-dark",document.body.classList.contains("dark")?"1":"0");};
  document.getElementById("themeBtn").onclick=toggle;document.getElementById("themeBtnTop").onclick=toggle;document.getElementById("myProfileShortcut").onclick=()=>go("profile");
  if(localStorage.getItem("sunshine-dark")==="1")document.body.classList.add("dark");
}
async function go(tab){activeTab=tab;await render();}
async function render(){try{
 if(activeTab==="home")return await home();
 if(activeTab==="chat")return await chat();
 if(activeTab==="notifications")return await notifications();
 if(activeTab==="settings")return await settingsPage();
 if(activeTab==="profile")return await profile(me.id);
 if(activeTab==="report")return reportPage();
 if(activeTab==="rules"){layout(`<section class="panel rules-page"><h2>Правила сообщества</h2>${COMMUNITY_RULES.map((r,i)=>`<article class="rule-item"><b>${i+1}.</b> ${esc(r.replace(/^\d+\.\s*/,""))}</article>`).join("")}</section>`,"Правила сообщества");return;}
 if(activeTab==="admin")return await admin();
 }catch(e){toast(e.message);}}
async function home(){
 const d=await api("/posts?q="+encodeURIComponent(searchTerm)+"&category="+encodeURIComponent(currentFilter));
 const cards=d.posts.map(p=>`<article class="post-card post-card-v2" data-post="${p.id}"><div class="post-category-icon">${categoryIcon(p.category)}</div><div class="post-card-content"><div class="post-top"><span class="category">${esc(p.category)}</span><span class="muted">${date(p.created_at)}</span></div><h3>${esc(p.title)}</h3><p>${richText(p.body.slice(0,180))}${p.body.length>180?"…":""}</p><div class="meta"><button class="link-btn user-link" data-user-profile="${p.user_id}">${icon("user")} ${esc(p.username)}</button><span data-likes="${p.id}">♥ ${p.likes}</span><span data-comments="${p.id}">${icon("chat")} ${p.comments}</span><span class="idea-score">↕ ${p.idea_score||0}</span></div>${reactionBar("post",p.id,p.my_reaction||null,p.reactions||[])}</div></article>`).join("");
 layout(`<div class="content-grid"><section><input class="search" id="search" placeholder="⌕　Поиск по форуму..." value="${esc(searchTerm)}"><div class="chips">${["Все","Идеи","Проблемы","Вопросы","Жалобы","Новости"].map(c=>`<button class="chip ${currentFilter===c?"active":""}" data-filter="${c}">${c}</button>`).join("")}</div><div class="announcement"><span class="category">Важно</span><b>Добро пожаловать в Sunshine Forum!</b><p>Место, где идеи становятся лучше вместе ✦</p><span class="megaphone">📣</span></div><div class="section-head"><h2>Популярные темы</h2><span class="muted">${d.posts.length} публикаций</span></div>${cards||'<div class="panel empty"><span>☁️</span>Пока нет публикаций. Создай первую!</div>'}</section><aside class="right-col">
 <div class="side-box quick-actions"><h3>Быстрые действия</h3>
  <button class="quick-action" id="newPostSide">${icon("edit")}<span>Создать публикацию</span></button>
  <button class="quick-action" id="supportSide">${icon("chat")}<span>Написать в поддержку</span></button>
  <button class="quick-action" id="reportsSide">${icon("inbox")}<span>Открыть личные обращения</span></button>
 </div>
 <button class="sunshine-banner" id="sunshineBanner"><span class="banner-art">${icon("sparkles")}</span><span><b>Вместе делаем<br>Sunshine лучше</b><small>Делись идеями, сообщай о проблемах и помогай сообществу 💜</small></span><span class="banner-star">✦</span></button>
 <div class="side-box status-legend"><h3>Статусы обращений</h3><div class="status-pills"><span class="status-pill new">${icon("sparkles")} Новая</span><span class="status-pill review">${icon("clock")} На рассмотрении</span><span class="status-pill progress">${icon("loader")} В работе</span><span class="status-pill done">${icon("check")} Решена</span><span class="status-pill rejected">${icon("x")} Отклонена</span></div></div>
 <div class="side-box rules-card"><h3>Правила сообщества</h3><p class="muted">Наши общие договорённости помогают сохранять уютную атмосферу.</p><button class="link-btn" id="showRules">Читать все 10 правил →</button></div>
 </aside></div><button class="fab" id="newPost">＋</button>`);
 document.getElementById("search").oninput=e=>{searchTerm=e.target.value;clearTimeout(home.timer);home.timer=setTimeout(home,250);};
 document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{currentFilter=b.dataset.filter;home();});
 document.querySelectorAll("[data-post]").forEach(el=>el.onclick=()=>postDetail(el.dataset.post));document.querySelectorAll('[data-react-type="post"]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();try{const r=await api(`/posts/${btn.dataset.reactId}/reactions`,{method:"POST",body:JSON.stringify({reaction:btn.dataset.reaction})});const bar=btn.closest(".reaction-bar");bar.querySelectorAll("button").forEach(b=>b.classList.toggle("selected",b.dataset.reaction===r.mine));bar.querySelectorAll("small").forEach(x=>x.remove());r.counts.forEach(x=>{const b=bar.querySelector(`[data-reaction="${x.reaction}"]`);if(b){const n=document.createElement("small");n.textContent=x.count;b.append(n);}});}catch(err){toast(err.message);}});document.querySelectorAll("[data-user-profile]").forEach(el=>el.onclick=e=>{e.stopPropagation();profile(el.dataset.userProfile);});
 document.getElementById("newPost").onclick=()=>newPost();document.getElementById("newPostSide").onclick=()=>newPost();document.getElementById("supportSide").onclick=()=>go("report");document.getElementById("reportsSide").onclick=()=>go("report");document.getElementById("sunshineBanner").onclick=()=>go("report");document.getElementById("showRules").onclick=showRules;
}
function showRules(){const dlg=document.createElement("dialog");dlg.className="modal rules-modal";dlg.innerHTML=`<button class="modal-close">×</button><div class="eyebrow">☀ SUNSHINE COMMUNITY</div><h2>Правила сообщества</h2><div class="rules-list">${COMMUNITY_RULES.map(r=>`<article class="rule-item">${esc(r)}</article>`).join("")}</div><button class="primary wide" id="rulesOk">Понятно</button>`;document.body.append(dlg);dlg.showModal();dlg.querySelector(".modal-close").onclick=()=>dlg.close();dlg.querySelector("#rulesOk").onclick=()=>dlg.close();dlg.onclose=()=>dlg.remove();}
function insertFormat(area,token){const a=area.selectionStart,b=area.selectionEnd,selected=area.value.slice(a,b)||"текст",wrap=token==="link"?`[${selected}](https://)`:token+selected+token;area.setRangeText(wrap,a,b,"select");area.focus();}
function newPost(){
 const dlg=document.createElement("dialog");dlg.className="modal compose-modal";dlg.innerHTML=`<button class="modal-close">×</button><div class="eyebrow">SUNSHINE COMMUNITY</div><h2>Создать публикацию</h2><form id="postForm"><div class="compose-row"><select name="category" aria-label="Категория"><option>Идеи</option><option>Проблемы</option><option>Вопросы</option><option>Жалобы</option><option>Новости</option></select><input name="title" required minlength="4" maxlength="100" placeholder="Заголовок публикации"></div><div class="format-toolbar"><button type="button" data-format="**">B</button><button type="button" data-format="## ">H</button><button type="button" data-format="link">${icon("report")}</button><span>Markdown-форматирование</span></div><textarea name="body" required minlength="5" maxlength="4000" placeholder="Расскажи подробнее…"></textarea><div class="compose-tools"><details class="attach-menu"><summary>${icon("paperclip")} Прикрепить</summary><div class="attach-pop"><label>${icon("report")} Файлы и медиа<input type="file" name="files" multiple accept="image/*,video/mp4,video/webm,application/pdf,text/plain,.docx"></label><label>${icon("report")} Ссылка<input name="link" type="url" placeholder="https://example.com"></label><div class="poll-fields"><b>Опрос</b><input name="pollQuestion" maxlength="180" placeholder="Вопрос"><input name="pollOption1" maxlength="100" placeholder="Вариант 1"><input name="pollOption2" maxlength="100" placeholder="Вариант 2"><input name="pollOption3" maxlength="100" placeholder="Вариант 3 (необязательно)"><input name="pollOption4" maxlength="100" placeholder="Вариант 4 (необязательно)"></div></div></details><span class="muted" id="fileCount">Можно добавить до 5 файлов</span><button class="primary">Опубликовать</button></div></form>`;
 document.body.append(dlg);dlg.querySelector(".modal-close").onclick=()=>dlg.close();dlg.showModal();const area=dlg.querySelector('textarea[name="body"]');dlg.querySelectorAll("[data-format]").forEach(b=>b.onclick=()=>insertFormat(area,b.dataset.format));dlg.querySelector('input[type="file"]').onchange=e=>dlg.querySelector("#fileCount").textContent=e.target.files.length?`${e.target.files.length} файл(ов) выбрано`:"Можно добавить до 5 файлов";
 dlg.querySelector("form").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),files=fd.getAll("files").filter(f=>f.size);const bodyText=[fd.get("body"),fd.get("link")?`\n${fd.get("link")}`:""].join("");const pollOptions=[fd.get("pollOption1"),fd.get("pollOption2"),fd.get("pollOption3"),fd.get("pollOption4")].filter(Boolean);const payload={category:fd.get("category"),title:fd.get("title"),body:bodyText,pollQuestion:fd.get("pollQuestion"),pollOptions};const created=await api("/posts",{method:"POST",body:JSON.stringify(payload)});if(files.length){const up=new FormData();files.slice(0,5).forEach(f=>up.append("files",f));const uploaded=await api("/attachments",{method:"POST",body:up});await api("/attachments/attach",{method:"POST",body:JSON.stringify({ids:uploaded.files.map(f=>f.id),type:"post",target:created.id})});}dlg.close();dlg.remove();toast("Публикация опубликована!");home();}catch(err){toast(err.message);}};dlg.onclose=()=>dlg.remove();
}
async function postDetail(id){
 const d=await api("/posts/"+id),p=d.post;
 const dlg=document.createElement("dialog");dlg.className="modal topic-screen";dlg.innerHTML=`<button class="modal-close">×</button><span class="category">${esc(p.category)}</span><h2>${esc(p.title)}</h2><div class="muted">Автор: <button class="link-btn user-link" data-user-profile="${p.user_id}">${esc(p.username)}</button> · ${date(p.created_at)}</div><p class="detail-body">${richText(p.body)}</p>${(d.attachments||[]).map(a=>a.mime.startsWith("image/")?`<a href="${esc(a.url)}" target="_blank"><img class="post-attachment" src="${esc(a.url)}" alt="${esc(a.original_name)}"></a>`:a.mime.startsWith("video/")?`<video class="post-attachment" controls src="${esc(a.url)}"></video>`:`<p><a href="${esc(a.url)}" target="_blank">📎 ${esc(a.original_name)}</a></p>`).join("")}<div class="topic-actions"><div><span class="muted">Реакции</span>${reactionBar("post",id,p.my_reaction||null,p.reactions||[])}</div><div class="idea-vote"><span>Продвинуть идею</span><button id="ideaDown" class="vote-btn ${p.my_idea_vote===-1?"selected":""}">−</button><b id="ideaScore">${p.idea_score||0}</b><button id="ideaUp" class="vote-btn ${p.my_idea_vote===1?"selected":""}">＋</button></div>${p.user_id===me.id||["admin","moderator"].includes(me.role)?'<button class="link-btn" id="deletePost">Удалить</button>':""}</div>${d.poll?`<section class="poll-card"><h3>📊 ${esc(d.poll.question)}</h3>${d.poll.options.map(o=>`<label class="poll-option"><input type="radio" name="postPoll" value="${o.id}" ${d.poll.myVote===o.id?"checked":""}><span>${esc(o.label)}</span><small>${o.votes} голосов</small></label>`).join("")}<button class="primary soft" id="votePostPoll">Голосовать</button></section>`:""}<h3>Комментарии</h3><div id="comments">${d.comments.map(c=>`<div class="comment"><button class="link-btn user-link" data-user-profile="${c.user_id}">${esc(c.username)}</button><span class="muted">${date(c.created_at)}</span><p>${richText(c.body)}</p>${(c.attachments||[]).map(a=>a.mime.startsWith("image/")?`<a href="${esc(a.url)}" target="_blank"><img class="post-attachment" src="${esc(a.url)}" alt=""></a>`:a.mime.startsWith("video/")?`<video class="post-attachment" controls src="${esc(a.url)}"></video>`:`<a href="${esc(a.url)}" target="_blank">📎 ${esc(a.original_name)}</a>`).join("")}</div>`).join("")||'<p class="muted">Пока нет комментариев.</p>'}</div><form id="commentForm"><div class="field"><textarea name="body" maxlength="1000" placeholder="Комментарий или упоминание @ник..."></textarea><div id="commentMentionSuggestions" class="mention-suggestions"></div></div><div class="field"><label>Ссылка (необязательно)</label><input name="link" type="url" placeholder="https://example.com"></div><div class="field"><label>Вложения</label><input type="file" name="files" multiple accept="image/*,video/mp4,video/webm,application/pdf,.docx,.txt"></div><button class="primary wide">Отправить</button></form>`;document.body.append(dlg);dlg.querySelector(".modal-close").onclick=()=>dlg.close();dlg.showModal();dlg.querySelectorAll("[data-user-profile]").forEach(el=>el.onclick=e=>{e.preventDefault();e.stopPropagation();dlg.close();profile(el.dataset.userProfile);});
 const commentPeople=await api("/chat/users");
 dlg.querySelectorAll('[data-react-type="post"]').forEach(btn=>btn.onclick=async()=>{try{const r=await api(`/posts/${id}/reactions`,{method:"POST",body:JSON.stringify({reaction:btn.dataset.reaction})});const parent=btn.closest(".reaction-bar");parent.querySelectorAll("button").forEach(b=>b.classList.toggle("selected",b.dataset.reaction===r.mine));parent.querySelectorAll("small").forEach(x=>x.remove());r.counts.forEach(x=>{const b=parent.querySelector(`[data-reaction="${x.reaction}"]`);if(b){const n=document.createElement("small");n.textContent=x.count;b.append(n);}});}catch(e){toast(e.message);}});
 const voteIdea=async value=>{try{const r=await api(`/posts/${id}/idea-vote`,{method:"POST",body:JSON.stringify({value})});dlg.querySelector("#ideaScore").textContent=r.score;dlg.querySelector("#ideaUp").classList.toggle("selected",r.mine===1);dlg.querySelector("#ideaDown").classList.toggle("selected",r.mine===-1);}catch(e){toast(e.message);}};dlg.querySelector("#ideaUp").onclick=()=>voteIdea(1);dlg.querySelector("#ideaDown").onclick=()=>voteIdea(-1);
 const commentBox=dlg.querySelector('textarea[name="body"]'),suggestions=dlg.querySelector("#commentMentionSuggestions");
 commentBox.addEventListener("input",()=>{const before=commentBox.value.slice(0,commentBox.selectionStart),match=before.match(/@([\p{L}\p{N}_-]{1,24})$/u);if(!match){suggestions.innerHTML="";return;}const q=match[1].toLowerCase(),found=commentPeople.users.filter(u=>u.username.toLowerCase().startsWith(q)).slice(0,6);suggestions.innerHTML=found.map(u=>`<button type="button" class="mention-choice" data-mention="${esc(u.username)}">@${esc(u.username)}</button>`).join("");suggestions.querySelectorAll("[data-mention]").forEach(btn=>btn.onclick=()=>{const start=commentBox.selectionStart, prefix=commentBox.value.slice(0,start).replace(/@[\p{L}\p{N}_-]{1,24}$/u,"");const suffix=commentBox.value.slice(start);commentBox.value=prefix+"@"+btn.dataset.mention+" "+suffix;commentBox.focus();suggestions.innerHTML="";});});
 dlg.querySelector("#commentForm").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),files=fd.getAll("files").filter(f=>f.size);let attachmentIds=[];if(files.length){const up=new FormData();files.forEach(f=>up.append("files",f));const saved=await api("/attachments",{method:"POST",body:up});attachmentIds=saved.files.map(f=>f.id);}const commentBody=[String(fd.get("body")||"").trim(),String(fd.get("link")||"").trim()].filter(Boolean).join("\n");await api(`/posts/${id}/comments`,{method:"POST",body:JSON.stringify({body:commentBody,attachmentIds})});dlg.close();dlg.remove();postDetail(id);toast("Комментарий добавлен.");}catch(err){toast(err.message);}};
 const voteBtn=dlg.querySelector("#votePostPoll");if(voteBtn)voteBtn.onclick=async()=>{const selected=dlg.querySelector('input[name="postPoll"]:checked');if(!selected)return toast("Выбери вариант ответа.");try{await api(`/posts/${id}/poll/vote`,{method:"POST",body:JSON.stringify({optionId:Number(selected.value)})});dlg.close();dlg.remove();postDetail(id);toast("Голос учтён.");}catch(e){toast(e.message);}};
 const del=dlg.querySelector("#deletePost");if(del)del.onclick=async()=>{if(confirm("Удалить публикацию?")){await api(`/posts/${id}`,{method:"DELETE"});dlg.close();dlg.remove();home();}};
 dlg.onclose=()=>dlg.remove();
}
async function chat(){
 const [d,stats]=await Promise.all([api("/chat"),api("/chat/stats")]);
 layout(`<div class="chat-layout"><section class="panel chat-main"><div class="section-head"><h2>Общий чат</h2><span class="chat-statline"><b id="chatTotalUsers">${stats.totalUsers}</b> всего · <b id="chatOnlineUsers">${stats.onlineUsers}</b> в сети</span></div><div class="chat-box" id="chatBox">${d.messages.map(messageHTML).join("")}</div>${d.mutedUntil?`<p class="muted-warning">Вам временно запрещено писать до ${esc(d.mutedUntil)} UTC.</p>`:""}<form class="chat-send chat-compose-v2" id="chatForm"><div class="chat-input-wrap"><input name="body" maxlength="800" autocomplete="off" placeholder="Написать сообщение…" ${d.mutedUntil?"disabled":""}><div id="chatMentionSuggestions" class="mention-suggestions"></div></div><details class="attach-menu chat-attach"><summary>${icon("paperclip")}</summary><div class="attach-pop"><label>Файлы и фото<input type="file" name="files" multiple accept="image/*,video/mp4,video/webm,application/pdf,.docx,.txt"></label><label>Ссылка<input name="link" type="url" placeholder="https://…"></label><div class="poll-fields"><b>Опрос</b><input name="pollQuestion" placeholder="Вопрос"><input name="pollOption1" placeholder="Вариант 1"><input name="pollOption2" placeholder="Вариант 2"><input name="pollOption3" placeholder="Вариант 3"><input name="pollOption4" placeholder="Вариант 4"></div></div></details><button class="primary send-button" ${d.mutedUntil?"disabled":""}>➤</button><input type="hidden" name="pollOptions"></form><p class="muted chat-hint">Для упоминания начни вводить @ и выбери участника.</p></section><aside class="panel chat-participants"><div class="section-head"><h3>Участники</h3><span class="muted" id="participantCount">Загрузка…</span></div><div id="participantList" class="participant-list"></div></aside></div>`,"Общий чат");
 const box=document.getElementById("chatBox");box.scrollTop=box.scrollHeight;const people=await api("/chat/users"),input=document.querySelector('#chatForm input[name="body"]'),suggestions=document.getElementById("chatMentionSuggestions");
 const participantList=document.getElementById("participantList");document.getElementById("participantCount").textContent=people.users.length+" публичных";
 participantList.innerHTML=people.users.map(u=>`<button class="participant-item" type="button" data-user-profile="${u.id}"><span class="participant-avatar">${u.avatar?`<img src="${esc(u.avatar)}" alt="">`:icon("user")}</span><span class="participant-name"><b>${esc(u.username)}</b><small>${u.role==="admin"?"Администратор":u.role==="moderator"?"Модератор":"Участник"}</small></span><i class="presence-dot ${u.online?"online":""}" title="${u.online?"В сети":"Не в сети"}"></i></button>`).join("")||'<p class="muted">Пока нет участников.</p>';
 input.addEventListener("input",()=>{const before=input.value.slice(0,input.selectionStart),match=before.match(/(?:^|\s)@([\p{L}\p{N}_-]{0,24})$/u);if(!match){suggestions.innerHTML="";return;}const q=match[1].toLowerCase(),found=people.users.filter(u=>u.username.toLowerCase().startsWith(q)).slice(0,7);suggestions.innerHTML=found.map(u=>`<button type="button" class="mention-choice" data-mention="${esc(u.username)}">${esc(u.username)}</button>`).join("");suggestions.querySelectorAll("[data-mention]").forEach(b=>b.onclick=()=>{const a=input.selectionStart,prefix=input.value.slice(0,a).replace(/@[\p{L}\p{N}_-]{0,24}$/u,"@"),suffix=input.value.slice(a);input.value=prefix+b.dataset.mention+" "+suffix;input.focus();suggestions.innerHTML="";});});
 document.getElementById("chatForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),files=fd.getAll("files").filter(f=>f.size),body=[String(fd.get("body")||"").trim(),String(fd.get("link")||"").trim()].filter(Boolean).join("\n");fd.set("body",body);fd.set("pollOptions",JSON.stringify([fd.get("pollOption1"),fd.get("pollOption2"),fd.get("pollOption3"),fd.get("pollOption4")].filter(Boolean)));try{await api("/chat/message",{method:"POST",body:fd});e.target.reset();suggestions.innerHTML="";}catch(err){toast(err.message);}};
 bindChatModeration();document.querySelectorAll("[data-user-profile]").forEach(el=>el.onclick=e=>{e.stopPropagation();profile(el.dataset.userProfile);});
}
function bindChatModeration(){document.querySelectorAll('[data-react-type="chat"]').forEach(b=>b.onclick=async()=>{try{const r=await api(`/chat/${b.dataset.reactId}/reaction`,{method:"POST",body:JSON.stringify({reaction:b.dataset.reaction})});const bar=b.closest(".reaction-bar");bar.querySelectorAll("button").forEach(x=>x.classList.toggle("selected",x.dataset.reaction===r.mine));bar.querySelectorAll("small").forEach(x=>x.remove());r.counts.forEach(x=>{const target=bar.querySelector(`[data-reaction="${x.reaction}"]`);if(target){const n=document.createElement("small");n.textContent=x.count;target.append(n);}});}catch(e){toast(e.message);}});document.querySelectorAll("[data-chat-vote]").forEach(b=>b.onclick=async()=>{const id=b.dataset.chatVote,choice=document.querySelector(`input[name="chatpoll-${id}"]:checked`);if(!choice)return toast("Выбери вариант.");try{await api(`/chat/polls/${id}/vote`,{method:"POST",body:JSON.stringify({optionId:Number(choice.value)})});await chat();toast("Голос учтён.");}catch(e){toast(e.message);}});document.querySelectorAll("[data-chat-delete]").forEach(b=>b.onclick=async()=>{if(confirm("Удалить это сообщение?")){try{await api(`/chat/${b.dataset.chatDelete}`,{method:"DELETE"});}catch(e){toast(e.message);}}});document.querySelectorAll("[data-chat-ban]").forEach(b=>b.onclick=async()=>{if(confirm("Заблокировать этого пользователя?")){try{await api(`/admin/users/${b.dataset.chatBan}/ban`,{method:"POST",body:JSON.stringify({reason:"Нарушение правил общего чата"})});toast("Пользователь заблокирован.");}catch(e){toast(e.message);}}});document.querySelectorAll("[data-chat-mute]").forEach(b=>b.onclick=async()=>{const minutes=prompt("На сколько минут выдать мут? Варианты: 5, 15, 30, 60, 180, 360, 1440, 10080","15");if(!minutes)return;try{await api(`/admin/users/${b.dataset.chatMute}/mute`,{method:"POST",body:JSON.stringify({minutes:Number(minutes),reason:"Нарушение правил общего чата"})});toast("Мут выдан.");}catch(e){toast(e.message);}});}
function messageHTML(m){const canModerate=["admin","moderator"].includes(me.role);const canBan=canModerate&&m.user_id!==me.id&&m.role!=="admin"&&(me.role==="admin"||m.role==="user");return `<div class="bubble ${m.user_id===me.id?"mine":""}" data-chat-message="${m.id}"><small><button class="link-btn user-link" data-user-profile="${m.user_id}">${esc(m.username)}</button> · ${date(m.created_at)} ${m.role==="admin"?"· админ":m.role==="moderator"?"· модератор":""}</small>${richText(m.body)}${(m.attachments||[]).map(a=>a.mime.startsWith("image/")?`<a href="${esc(a.url)}" target="_blank"><img class="post-attachment" src="${esc(a.url)}" alt=""></a>`:a.mime.startsWith("video/")?`<video class="post-attachment" controls src="${esc(a.url)}"></video>`:`<a href="${esc(a.url)}" target="_blank">📎 ${esc(a.original_name)}</a>`).join("")}${m.poll?`<div class="chat-poll"><b>📊 ${esc(m.poll.question)}</b>${m.poll.options.map(o=>`<label><input type="radio" name="chatpoll-${m.poll.id}" value="${o.id}" ${m.poll.myVote===o.id?"checked":""}> ${esc(o.label)} <small>${o.votes}</small></label>`).join("")}<button class="link-btn" data-chat-vote="${m.poll.id}">Голосовать</button></div>`:""}${reactionBar("chat",m.id,m.myReaction,m.reactions||[])}${canModerate&&m.user_id!==me.id?`<div class="chat-actions"><button class="link-btn" data-chat-delete="${m.id}">Удалить</button>${canBan?`<button class="link-btn" data-chat-ban="${m.user_id}">Бан</button><button class="link-btn" data-chat-mute="${m.user_id}">Мут</button>`:""}</div>`:""}</div>`;}
async function notifications(){
 const d=await api("/notifications");await api("/notifications/read",{method:"POST",body:"{}"});unreadCount=0;
 layout(`<section class="panel"><h2>Уведомления</h2>${d.notifications.map(n=>`<button class="notification-item ${n.read?"is-read":"is-new"}" data-notification-type="${esc(n.target_type||"")}" data-notification-id="${n.target_id||""}"><span class="category">${n.read?"Просмотрено":"Новое"}</span><p>${esc(n.text)}</p><span class="muted">${date(n.created_at)}</span><span class="notification-open">Открыть →</span></button>`).join("")||'<div class="empty"><span>✧</span>Пока уведомлений нет.</div>'}</section>` ,"Уведомления");
 document.querySelectorAll("[data-notification-type]").forEach(el=>el.onclick=async()=>{const type=el.dataset.notificationType,id=el.dataset.notificationId;if(type==="post"&&id){await postDetail(id);return;}if(type==="report"&&id){await reportThread(id);return;}if(type==="chat"){await go("chat");if(id){const target=document.querySelector(`[data-chat-message="${CSS.escape(id)}"]`);if(target)target.scrollIntoView({behavior:"smooth",block:"center"});else toast("Сообщение больше недоступно или не загружено.");}return;}if((type==="profile"||type==="user")&&id){await profile(Number(id));return;}if(!type||!id){await go("home");toast("Это старое уведомление без прямой ссылки. Открыта главная лента.");return;}await go("notifications");toast("Для этого типа уведомления пока нет отдельной страницы.");});
}
async function profile(id){
 const [d,ach]=await Promise.all([api("/profile/"+id),api("/achievements/"+id)]);const activity=id===me.id?await api("/profile/"+id+"/activity"):null;
 layout(`<section class="panel"><div class="profile-head"><div class="avatar">${d.user.avatar?`<img src="${esc(d.user.avatar)}?v=${Date.now()}" alt="Аватар ${esc(d.user.username)}">`:"🌸"}</div><div><h2>${esc(d.user.username)}</h2><span class="category">${d.user.role==="admin"?"Администратор":d.user.role==="moderator"?"Модератор":"Пользователь"}</span><p class="muted">Участник с ${new Date(d.user.created_at+"Z").toLocaleDateString("ru-RU")}</p></div></div><p>${esc(d.user.bio||"Пока нет описания профиля.")}</p>${id===me.id?'<button class="primary soft" id="editBio">Редактировать профиль</button>':""}<div class="stats"><div class="stat-card"><strong>${d.stats.posts}</strong><span>публикаций</span></div><div class="stat-card"><strong>${d.stats.reputation}</strong><span>реакций</span></div><div class="stat-card"><strong>${d.posts.reduce((a,p)=>a+p.comments,0)}</strong><span>комментариев</span></div></div><div class="achievement-heading"><h2>Достижения</h2><span class="muted">${ach.achievements.filter(a=>a.earned).length} / ${ach.achievements.length} получено</span></div><div class="achievement-grid">${ach.achievements.map(a=>`<div class="achievement ${a.earned?"earned":"locked"}"><span class="achievement-icon">${a.icon}</span><div><b>${esc(a.title)}</b><small>${esc(a.description)}</small></div>${a.earned?'<span class="earned-mark">✓</span>':'<span class="lock-mark">🔒</span>'}</div>`).join("")}</div>${id===me.id?`<div class="profile-activity"><h2>Моя активность</h2><div class="activity-columns"><section><h3>Мои комментарии</h3>${activity.comments.map(c=>`<div class="comment activity-entry"><a href="#" data-activity-post="${c.post_id}"><b>${esc(c.title)}</b></a><p>${richText(c.body)}</p>${(c.attachments||[]).map(a=>a.mime.startsWith("image/")?`<a href="${esc(a.url)}" target="_blank"><img class="activity-attachment" src="${esc(a.url)}" alt="${esc(a.original_name)}"></a>`:a.mime.startsWith("video/")?`<video class="activity-attachment" controls src="${esc(a.url)}"></video>`:`<a href="${esc(a.url)}" target="_blank">📎 ${esc(a.original_name)}</a>`).join("")}<small class="muted">${date(c.created_at)}</small></div>`).join("")||'<p class="muted">Комментариев пока нет.</p>'}</section><section><h3>Мои реакции</h3>${activity.reactions.map(r=>`<div class="comment activity-entry"><a href="#" data-activity-post="${r.post_id}"><b>${esc(r.title)}</b></a><p class="muted">♡ Вы поставили реакцию на публикацию пользователя ${esc(r.username)}</p><small class="muted">${date(r.created_at)}</small></div>`).join("")||'<p class="muted">Вы пока не ставили реакции.</p>'}</section></div></div>`:""}<h2>Публикации</h2>${d.posts.map(p=>`<article class="post-card" data-post="${p.id}"><span class="category">${esc(p.category)}</span><h3>${esc(p.title)}</h3><div class="meta"><span data-likes="${p.id}">♡ ${p.likes}</span><span data-comments="${p.id}">▢ ${p.comments}</span></div></article>`).join("")||'<p class="muted">Публикаций пока нет.</p>'}</section>`,"Профиль");
 document.querySelectorAll("[data-post]").forEach(el=>el.onclick=()=>postDetail(el.dataset.post));document.querySelectorAll('[data-react-type="post"]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();try{const r=await api(`/posts/${btn.dataset.reactId}/reactions`,{method:"POST",body:JSON.stringify({reaction:btn.dataset.reaction})});const bar=btn.closest(".reaction-bar");bar.querySelectorAll("button").forEach(b=>b.classList.toggle("selected",b.dataset.reaction===r.mine));bar.querySelectorAll("small").forEach(x=>x.remove());r.counts.forEach(x=>{const b=bar.querySelector(`[data-reaction="${x.reaction}"]`);if(b){const n=document.createElement("small");n.textContent=x.count;b.append(n);}});}catch(err){toast(err.message);}});document.querySelectorAll("[data-user-profile]").forEach(el=>el.onclick=e=>{e.stopPropagation();profile(el.dataset.userProfile);});document.querySelectorAll("[data-activity-post]").forEach(a=>a.onclick=e=>{e.preventDefault();postDetail(a.dataset.activityPost);});
 const edit=document.getElementById("editBio");if(edit)edit.onclick=()=>{const dlg=document.createElement("dialog");dlg.className="modal";dlg.innerHTML=`<button class="modal-close">×</button><h2>Редактировать профиль</h2><form id="profileForm"><div class="field"><label>Никнейм</label><input name="username" required minlength="3" maxlength="24" value="${esc(d.user.username)}"></div><div class="field"><label>О себе</label><textarea name="bio" maxlength="180">${esc(d.user.bio||"")}</textarea></div><div class="field"><label>Аватар</label><input type="file" name="avatar" accept="image/png,image/jpeg,image/webp,image/gif"></div><button class="primary wide">Сохранить</button></form>`;document.body.append(dlg);dlg.showModal();dlg.querySelector(".modal-close").onclick=()=>dlg.close();dlg.querySelector("form").onsubmit=async ev=>{ev.preventDefault();try{const fd=new FormData(ev.target);await api("/profile",{method:"PATCH",body:JSON.stringify({username:fd.get("username"),bio:fd.get("bio")})});const avatar=fd.get("avatar");if(avatar&&avatar.size){const af=new FormData();af.append("avatar",avatar);const result=await api("/avatar",{method:"POST",body:af});me=result.user;}else me=(await api("/me")).user;dlg.close();dlg.remove();await profile(me.id);toast("Профиль сохранён.");}catch(err){toast(err.message);}};dlg.onclose=()=>dlg.remove();};
}
async function reportPage(){
 const existing=await api("/reports");
 layout(`<section class="panel"><div class="announcement" style="text-align:center"><div style="font-size:32px">🛡️</div><h2>Приватное обращение</h2><p>Создайте обращение — администрация сможет ответить вам в отдельной переписке.</p></div><form id="reportForm"><div class="field"><label>Тема обращения *</label><select name="topic" required><option value="">Выберите тему</option><option>Проблема с аккаунтом</option><option>Жалоба на пользователя</option><option>Техническая проблема</option><option>Предложение</option><option>Другое</option></select></div><div class="field"><label>Описание *</label><textarea name="body" required minlength="10" maxlength="2000" placeholder="Подробно опишите ситуацию..."></textarea></div><div class="field"><label>Вложения</label><input type="file" name="files" multiple accept="image/*,video/mp4,video/webm,application/pdf,.docx,.txt"></div><button class="primary wide">Отправить обращение</button></form></section><section class="panel"><h2>${["admin","moderator"].includes(me.role)?"Обращения пользователей":"Мои обращения"}</h2><div id="myReports">${existing.reports.map(r=>`<div class="comment report-row"><b>#${r.id} · ${esc(r.topic)}</b><span class="status">${esc(r.status)}</span><p>${esc(r.body)}</p><button class="link-btn" data-open-report="${r.id}">Открыть переписку</button></div>`).join("")||'<p class="muted">Обращений пока нет.</p>'}</div></section>`,"Приватные обращения");
 document.getElementById("reportForm").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),files=fd.getAll("files").filter(f=>f.size);const r=await api("/reports",{method:"POST",body:JSON.stringify({topic:fd.get("topic"),body:fd.get("body")})});if(files.length){const up=new FormData();files.forEach(f=>up.append("files",f));const saved=await api("/attachments",{method:"POST",body:up});await api("/attachments/attach",{method:"POST",body:JSON.stringify({ids:saved.files.map(f=>f.id),type:"report",target:r.id})});}toast("Обращение отправлено администрации.");await reportPage();}catch(err){toast(err.message);}};
 document.querySelectorAll("[data-open-report]").forEach(b=>b.onclick=()=>reportThread(b.dataset.openReport));
}
async function reportThread(id){
 const [data,thread]=await Promise.all([api("/reports"),api(`/reports/${id}/messages`)]);
 const ticket=data.reports.find(r=>Number(r.id)===Number(id));
 const dlg=document.createElement("dialog");dlg.className="modal thread-modal";
 dlg.innerHTML=`<button class="modal-close">×</button><h2>Обращение #${id}</h2><p class="muted">${esc(ticket?.topic||"Переписка с администрацией")} · ${esc(ticket?.status||"")}</p><div class="thread-messages" id="threadMessages">${[...thread.messages,...thread.replies].map(m=>`<div class="comment"><b>${esc(m.username)} ${m.user_id===me.id?"(вы)":""}</b><span class="muted">${date(m.created_at)}</span><p>${esc(m.body)}</p></div>`).join("")||'<p class="muted">Сообщений пока нет.</p>'}${thread.attachments.map(a=>`<div class="comment">${a.mime.startsWith("image/")?`<a href="${esc(a.url)}" target="_blank"><img class="post-attachment" src="${esc(a.url)}" alt="${esc(a.original_name)}"></a>`:a.mime.startsWith("video/")?`<video class="post-attachment" controls src="${esc(a.url)}"></video>`:`<a href="${esc(a.url)}" target="_blank">📎 ${esc(a.original_name)}</a>`}</div>`).join("")}</div><form id="threadForm"><div class="field"><textarea name="body" maxlength="2000" placeholder="Написать ответ..."></textarea></div><div class="field"><label>Прикрепить файлы</label><input type="file" name="files" multiple accept="image/*,video/mp4,video/webm,application/pdf,.docx,.txt"></div><button class="primary wide">Отправить ответ</button></form>`;
 document.body.append(dlg);dlg.showModal();dlg.querySelector(".modal-close").onclick=()=>dlg.close();dlg.querySelector("form").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),body=String(fd.get("body")||"").trim(),files=fd.getAll("files").filter(f=>f.size);if(!body&&!files.length)throw new Error("Напишите ответ или прикрепите файл.");if(body)await api(`/reports/${id}/messages`,{method:"POST",body:JSON.stringify({body})});if(files.length){const up=new FormData();files.forEach(f=>up.append("files",f));const saved=await api("/attachments",{method:"POST",body:up});await api("/attachments/attach",{method:"POST",body:JSON.stringify({ids:saved.files.map(f=>f.id),type:"report",target:Number(id)})});}dlg.close();dlg.remove();await reportThread(id);toast("Ответ отправлен.");}catch(err){toast(err.message);}};dlg.onclose=()=>dlg.remove();
}
async function settingsPage(){const d=await api("/settings"),s=d.settings;layout(`<section class="panel"><h2>Настройки уведомлений и приватности</h2><form id="settingsForm"><label class="setting-row"><span>Уведомления о лайках</span><input type="checkbox" name="notify_likes" ${s.notify_likes?"checked":""}></label><label class="setting-row"><span>Уведомления о комментариях</span><input type="checkbox" name="notify_comments" ${s.notify_comments?"checked":""}></label><label class="setting-row"><span>Уведомления об обращениях</span><input type="checkbox" name="notify_reports" ${s.notify_reports?"checked":""}></label><label class="setting-row"><span>Закрытый профиль <small class="muted">Профиль и публикации будут видны только вам и сотрудникам.</small></span><input type="checkbox" name="private_profile" ${s.private_profile?"checked":""}></label><button class="primary">Сохранить настройки</button></form><p class="muted">Тема оформления сохраняется отдельно на этом устройстве.</p></section>` ,"Настройки");document.getElementById("settingsForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={};["notify_likes","notify_comments","notify_reports","private_profile"].forEach(k=>payload[k]=f.has(k));await api("/settings",{method:"PATCH",body:JSON.stringify(payload)});toast("Настройки сохранены.");};}
async function admin(){
 const d=await api("/admin/overview");
 layout(`<section class="panel"><h2>Статистика</h2><div class="stats"><div class="stat-card"><strong>${d.stats.users}</strong><span>пользователей</span></div><div class="stat-card"><strong>${d.stats.posts}</strong><span>публикаций</span></div><div class="stat-card"><strong>${d.stats.reports}</strong><span>новых обращений</span></div><div class="stat-card"><strong>${d.stats.comments}</strong><span>комментариев</span></div><div class="stat-card"><strong>${d.stats.reactions}</strong><span>реакций</span></div><div class="stat-card"><strong>${d.stats.activeUsers}</strong><span>активных</span></div></div></section><section class="panel"><h2>Поиск пользователей</h2><input class="search" id="userSearch" placeholder="Введите никнейм (от 2 символов)..."><div id="userSearchResults"></div></section><section class="panel"><h2>Пользователи</h2><p class="muted">Модераторы могут управлять блокировками обычных пользователей. Изменение ролей и управление блокировками сотрудников доступны только администраторам.</p><div class="admin-user-tabs"><button class="primary soft" id="showActiveUsers">Активные</button><button class="primary soft" id="showBlockedUsers">Заблокированные</button></div><div class="table-wrap"><table><thead><tr><th>Пользователь</th><th>Роль</th><th>Статус</th><th>Действие</th></tr></thead><tbody id="adminUsersRows">${d.users.filter(u=>u.status==="active").map(u=>`<tr><td>${esc(u.username)}<br><span class="muted">${esc(u.email)}</span></td><td><select data-role="${u.id}" ${u.id===me.id||me.role!=="admin"?"disabled":""}><option value="user" ${u.role==="user"?"selected":""}>user</option><option value="moderator" ${u.role==="moderator"?"selected":""}>moderator</option><option value="admin" ${u.role==="admin"?"selected":""}>admin</option></select></td><td>${esc(u.status)}</td><td>${u.id===me.id||u.role!=="user"?"—":`<button class="link-btn" data-user="${u.id}" data-status="blocked">Заблокировать</button>`}</td></tr>`).join("")||'<tr><td colspan="4">Нет активных пользователей в этом списке.</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Приватные обращения</h2>${d.reports.map(r=>`<div class="comment"><b>#${r.id} · ${esc(r.topic)}</b> · ${esc(r.username)} <span class="status">${esc(r.status)}</span><p>${esc(r.body)}</p><button class="link-btn" data-open-report="${r.id}">Открыть переписку</button><select data-report="${r.id}" aria-label="Статус обращения"><option ${r.status==="Новая"?"selected":""}>Новая</option><option ${r.status==="В работе"?"selected":""}>В работе</option><option ${r.status==="Решена"?"selected":""}>Решена</option><option ${r.status==="Отклонена"?"selected":""}>Отклонена</option></select></div>`).join("")||'<p class="muted">Обращений пока нет.</p>'}</section><section class="panel"><h2>Журнал аудита</h2><button class="primary soft" id="auditBtn" aria-expanded="false">Показать последние действия</button><div id="auditList" class="audit-list hidden"></div></section><section class="panel"><h2>Последние публикации</h2>${d.posts.map(p=>`<div class="comment"><b>${esc(p.title)}</b><span class="muted"> · ${esc(p.username)} · ${esc(p.category)}</span></div>`).join("")}</section>`,"Админ-панель");
 const usersRows=document.getElementById("adminUsersRows");
 const renderAdminUsers=users=>{usersRows.innerHTML=users.map(u=>`<tr><td>${esc(u.username)}<br><span class="muted">${esc(u.email)}</span></td><td>${esc(u.role)}</td><td>${esc(u.status)}</td><td>${u.status==="blocked"?(u.role==="user"||me.role==="admin"?`<button class="link-btn" data-unban="${u.id}">Разблокировать</button>`:"—"):u.id!==me.id&&u.role==="user"?`<button class="link-btn" data-user="${u.id}" data-status="blocked">Заблокировать</button>`:"—"}</td></tr>`).join("")||'<tr><td colspan="4">Список пуст.</td></tr>';bindUserActions();};
 const bindUserActions=()=>{usersRows.querySelectorAll("[data-user]").forEach(b=>b.onclick=async()=>{try{await api(`/admin/users/${b.dataset.user}/ban`,{method:"POST",body:JSON.stringify({reason:"Блокировка из панели управления"})});toast("Пользователь заблокирован.");document.getElementById("showActiveUsers").click();}catch(e){toast(e.message);}});usersRows.querySelectorAll("[data-unban]").forEach(b=>b.onclick=async()=>{try{await api(`/admin/users/${b.dataset.unban}/unban`,{method:"POST",body:"{}"});toast("Пользователь разблокирован.");document.getElementById("showBlockedUsers").click();}catch(e){toast(e.message);}});};
 bindUserActions();
 document.getElementById("showActiveUsers").onclick=()=>{const rows=d.users.filter(u=>u.status==="active");renderAdminUsers(rows);};
 document.getElementById("showBlockedUsers").onclick=async()=>{try{const r=await api("/admin/users/blocked");renderAdminUsers(r.users);}catch(e){toast(e.message);}};
 document.querySelectorAll("[data-report]").forEach(sel=>sel.onchange=async()=>{await api(`/admin/reports/${sel.dataset.report}`,{method:"PATCH",body:JSON.stringify({status:sel.value})});toast("Статус обращения обновлён.");});
 document.querySelectorAll("[data-role]").forEach(sel=>sel.onchange=async()=>{try{await api(`/admin/users/${sel.dataset.role}/role`,{method:"PATCH",body:JSON.stringify({role:sel.value})});toast("Роль обновлена.");}catch(e){toast(e.message);admin();}});
 document.querySelectorAll("[data-open-report]").forEach(b=>b.onclick=()=>reportThread(b.dataset.openReport));
 const search=document.getElementById("userSearch");let timer;search.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=search.value.trim(),box=document.getElementById("userSearchResults");if(q.length<2){box.innerHTML="";return;}try{const r=await api("/admin/users/search?q="+encodeURIComponent(q));box.innerHTML=r.users.map(u=>`<div class="comment"><b>${esc(u.username)}</b> · ${esc(u.role)} · ${esc(u.status)}<br><span class="muted">${esc(u.email)}</span> ${u.role!=="admin"&&u.id!==me.id?`<button class="link-btn" data-search-ban="${u.id}">Заблокировать</button>`:""}</div>`).join("")||'<p class="muted">Никого не найдено.</p>';box.querySelectorAll("[data-search-ban]").forEach(b=>b.onclick=async()=>{if(confirm("Заблокировать этого пользователя?")){await api(`/admin/users/${b.dataset.searchBan}/ban`,{method:"POST",body:JSON.stringify({reason:"Блокировка из панели управления"})});toast("Пользователь заблокирован.");admin();}});}catch(e){toast(e.message);}},250);};
 document.getElementById("auditBtn").onclick=async()=>{const list=document.getElementById("auditList"),btn=document.getElementById("auditBtn");if(!list.classList.contains("hidden")){list.classList.add("hidden");btn.textContent="Показать последние действия";btn.setAttribute("aria-expanded","false");return;}const a=await api("/admin/audit");list.innerHTML=a.logs.map(x=>`<div class="comment"><b>${esc(x.username||"Система")}</b> — ${esc(x.action)} <span class="muted">${date(x.created_at)}</span><div class="muted">${esc(x.target_type)} #${x.target_id||"—"} ${esc(x.details)}</div></div>`).join("")||"<p class=muted>Записей пока нет.</p>";list.classList.remove("hidden");btn.textContent="Свернуть журнал аудита";btn.setAttribute("aria-expanded","true");};
}
async function boot(){
 if(!me){app.innerHTML=`<section class="splash"><div class="splash-art"><span class="sun-cloud sun">☀</span><span class="sun-cloud cloud c1">☁</span><span class="sun-cloud cloud c2">☁</span><span class="cloud-extra one">☁</span><span class="cloud-extra two">☁</span><span class="moon">☾</span><span class="sparkle">✦</span><span class="star s1">✧</span><span class="star s2">✦</span><span class="star s3">✧</span><span class="star s4">✦</span></div><div class="brand-large">Sunshine<br>Forum</div><p>Общайся. Предлагай.<br>Влияй.</p><button class="primary" id="startBtn">Начать</button></section>`;document.getElementById("startBtn").onclick=()=>showAuth("login");return;}
 if(socket)socket.disconnect();socket=io();
 socket.on("presence:update",async d=>{const n=document.getElementById("chatOnlineUsers");if(n)n.textContent=d.onlineUsers;const list=document.getElementById("participantList");if(list){try{const r=await api("/chat/users");r.users.forEach(u=>{const item=list.querySelector(`[data-user-profile="${u.id}"] .presence-dot`);if(item){item.classList.toggle("online",u.online);item.title=u.online?"В сети":"Не в сети";}});}catch{}}});
 socket.on("chat:message",m=>{const box=document.getElementById("chatBox");if(box){box.insertAdjacentHTML("beforeend",messageHTML(m));box.scrollTop=box.scrollHeight;bindChatModeration();box.querySelectorAll("[data-user-profile]").forEach(el=>el.onclick=e=>{e.stopPropagation();profile(el.dataset.userProfile);});}});
 socket.on("chat:deleted",d=>{document.querySelector(`[data-chat-message="${d.id}"]`)?.remove();});
 socket.on("chat:error",d=>toast(d.message));
 socket.on("chat:muted",d=>{const input=document.querySelector("#chatForm input");if(input){input.disabled=true;input.placeholder="Вам выдан временный мут";}toast("Вам временно ограничили отправку сообщений.");});
 socket.on("chat:unmuted",()=>{const input=document.querySelector("#chatForm input");if(input){input.disabled=false;input.placeholder="Написать сообщение... Используй @ник для упоминания";}toast("Ограничение чата снято.");});
 socket.on("post:updated",d=>{document.querySelectorAll(`[data-likes="${d.id}"]`).forEach(x=>x.textContent="♡ "+d.likes);document.querySelectorAll(`[data-comments="${d.id}"]`).forEach(x=>x.textContent="▢ "+d.comments);});
 socket.on("account:blocked",()=>{alert("Ваш аккаунт заблокирован администрацией.");location.reload();});
 socket.on("connect_error",()=>toast("Не удалось подключиться к чату."));
 socket.on("notification",n=>{unreadCount=n.unread||unreadCount+1;const badge=document.getElementById("unreadBadge");if(badge)badge.textContent=unreadCount?String(unreadCount):"";toast(n.text||"Новое уведомление");});
 await render();
}
(async()=>{try{const d=await api("/me");me=d.user;unreadCount=d.unread||0;}catch{}await boot();})();
